#!/usr/bin/env python3

from traits.api import *

class A(HasTraits):
    foo = Union(None, Int)

class B(A):
    foo = 5

b = B()
print("Initial value:", b.foo)
try:
    result = b.foo -= 1
    print("Result:", result)
except Exception as e:
    print("Error:", type(e).__name__, str(e))

